from collections.abc import Callable, Generator
from typing import Any, TypeVar

from typing_extensions import ParamSpec

from expression.core import Builder, Ok, Result, pipe, result


_TSource = TypeVar("_TSource")
_TResult = TypeVar("_TResult")
_TError = TypeVar("_TError")
_P = ParamSpec("_P")


class ResultBuilder(Builder[_TSource, Result[Any, _TError]]):
    def bind(
        self,
        xs: Result[_TSource, _TError],
        fn: Callable[[_TSource], Result[_TResult, _TError]],
    ) -> Result[_TResult, _TError]:
        return pipe(xs, result.bind(fn))

    def return_(self, x: _TSource) -> Result[_TSource, _TError]:
        return Ok(x)

    def return_from(self, xs: Result[_TSource, _TError]) -> Result[_TSource, _TError]:
        return xs

    def combine(self, xs: Result[_TSource, _TError], ys: Result[_TSource, _TError]) -> Result[_TSource, _TError]:
        return xs.bind(lambda _: ys)

    def zero(self) -> Result[_TSource, _TError]:
        return Ok(None)

    def __call__(
        self,  # Ignored self parameter
        fn: Callable[
            _P,
            Generator[_TSource | None, _TSource, _TSource | None] | Generator[_TSource | None, None, _TSource | None],
        ],
    ) -> Callable[_P, Result[_TSource, _TError]]:
        return super().__call__(fn)


class AsyncResultBuilder(ResultBuilder[_TSource, _TError]):
    """Async version of ResultBuilder for async computations."""

    async def _send(
        self,
        gen: Generator[Any, Any, Any],
        done: list[bool],
        value: _TSource | None = None,
    ) -> Result[_TSource, _TError]:
        try:
            # Check if the generator supports send method (i.e. is a true generator)
            # If it doesn't support send, it's likely an iterator (like list_iterator) 
            # that we should handle with next() instead
            try:
                yielded = gen.send(value)
                return self.return_(yielded)
            except AttributeError as ex:
                if "'object' object has no attribute 'send'" in str(ex) or "has no attribute 'send'" in str(ex):
                    # Handle iterators that don't support send (like list_iterator)
                    try:
                        yielded = next(gen)
                        return self.return_(yielded)
                    except StopIteration as stop_ex:
                        done.append(True)
                        # Return of a value in the generator produces StopIteration with a value
                        if stop_ex.value is not None:
                            return self.return_(stop_ex.value)
                        raise
                raise  # Re-raise if it's a different AttributeError
        except StopIteration as ex:
            done.append(True)
            # Return of a value in the generator produces StopIteration with a value
            if ex.value is not None:
                return self.return_(ex.value)
            raise
        except RuntimeError:
            done.append(True)
            raise StopIteration


    def __call__(
        self,  # Ignored self parameter
        fn: Callable[
            _P,
            Generator[_TSource | None, _TSource, _TSource | None] | Generator[_TSource | None, None, _TSource | None],
        ],
    ) -> Callable[_P, Result[_TSource, _TError]]:
        """Async result builder."""

        async def async_wrapper(*args: _P.args, **kw: _P.kwargs) -> Result[_TSource, _TError]:
            gen = fn(*args, **kw)
            done: list[bool] = []

            result: Result[_TSource, _TError] | None = None

            async def binder(value: Any) -> Result[_TSource, _TError]:
                ret = self._send(gen, done, value)
                # We need to await the async nature of _send
                return await ret

            try:
                result = await self._send(gen, done)

                while not done:
                    cont = await self.bind(result, binder)

                    # Combine every result except the first
                    if result is None:
                        result = cont
                    else:
                        result = await self.combine(result, cont)
            except StopIteration:
                pass

            # If anything returns `None` (i.e raises StopIteration without a value) then
            # we expect the effect to have a zero method implemented.
            if result is None:
                result = self.zero()

            return await self.run(result)

        return async_wrapper


class TryBuilder(ResultBuilder[_TSource, Exception]): ...


__all__ = ["ResultBuilder", "AsyncResultBuilder", "TryBuilder"]

