from collections.abc import Callable, Iterable
from typing import Any, TypeVar

from expression.collections import seq
from expression.core import Builder


_TSource = TypeVar("_TSource")
_TResult = TypeVar("_TResult")


class SeqBuilder(Builder[_TSource, Iterable[Any]]):
    def bind(self, xs: Iterable[_TSource], fn: Callable[[_TSource], Iterable[_TResult]]) -> Iterable[_TResult]:
        result = []
        for x in xs:
            result.extend(fn(x))
        return result if result else seq.empty

    def return_(self, x: _TSource) -> Iterable[_TSource]:
        return seq.singleton(x)

    def return_from(self, xs: Iterable[_TSource]) -> Iterable[_TSource]:
        return xs

    def combine(self, xs: Iterable[_TSource], ys: Iterable[_TSource]) -> Iterable[_TSource]:
        ret = seq.concat(xs, ys)
        return ret

    def zero(self) -> Iterable[_TSource]:
        return seq.empty


__all__ = ["SeqBuilder"]

import functools
from collections.abc import Callable, Iterable
from itertools import accumulate
from typing import Any, Optional

import pytest
from hypothesis import given  # type: ignore
from hypothesis import strategies as st

from expression import Nothing, Option, Some, effect, option, pipe
from expression.collections import Seq, seq


def test_seq_empty():
    @effect.seq[int]()
    def fn():
        while False:
            yield

    ys = fn()

    assert isinstance(ys, Iterable)
    assert list(ys) == []


def test_seq_yield():
    @effect.seq[int]()
    def fn():
        yield 42

    ys = fn()

    assert list(ys) == [42]


@given(st.lists(st.integers(), max_size=10))  # type: ignore
def test_seq_yield_for_in(xs: list[int]):
    @effect.seq[int]()
    def fn():
        for x in xs:
            yield x

    ys = fn()

    assert list(ys) == xs


